content:
{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Capable of giving signed informed consent as described in Appendix A, which includes compliance with the requirements and restrictions listed in the ICF and in this protocol.",
      "quote": "Capable of giving signed informed consent as described in Appendix A"
    },
    {
      "kind": "inclusion",
      "text": "Provision of signed and dated written Optional Genetic Research Information informed consent prior to collection of samples for optional genetic research that supports the Genomic Initiative (see Appendix D).",
      "quote": "Provision of signed and dated written Optional Genetic Research Information informed consent prior to collection of samples for optional genetic research"
    },
    {
      "kind": "inclusion",
      "text": "Provision of signed and dated written ICF prior to any mandatory study specific procedures, sampling, or analyses.",
      "quote": "Provision of signed and dated written ICF prior to any mandatory study specific procedures, sampling, or analyses."
    },
    {
      "kind": "inclusion",
      "text": "Male and female patients must be at least 18 years of age at the time of signing the ICF.",
      "quote": "Male and female patients must be at least 18 years of age at the time of signing the ICF."
    },
    {
      "kind": "inclusion",
      "text": "Patients with unresectable and/or metastatic solid tumors with pre-specified HER2 mutations, who have progressed following prior treatment, or who have no satisfactory alternative treatment options including approved second line therapies in the specific tumor type. Prior HER2 targeting therapy is permitted.",
      "quote": "Patients with unresectable and/or metastatic solid tumors with pre-specified HER2 mutations, who have progressed following prior treatment, or who have no satisfactory alternative treatment options"
    },
    {
      "kind": "inclusion",
      "text": "Patients with tumors harboring any of the following HER2 mutations: S310F, S310Y, G660D, R678Q, D769Y, D769H, V777L, Y772_A775dup / A775_G776insYVMA, L755S, G778_P780dup / P780_Y781insGSP, T862A, and V842I locally determined by NGS or a validated nucleic acid-based methodology (eg, qPCR, digital PCR) on tumor tissue.",
      "quote": "Patients with tumors harboring any of the following HER2 mutations: S310F, S310Y, G660D, R678Q, D769Y, D769H, V777L, Y772_A775dup / A775_G776insYVMA, L755S, G778_P780dup / P780_Y781insGSP, T862A, and V842I"
    },
    {
      "kind": "inclusion",
      "text": "All patients must provide an existing FFPE tumor sample for retrospective central HER2 testing. The sample should be obtained at the time of diagnosis of metastatic or locally advanced unresectable disease. If not available, a pre-enrolment sample obtained upon diagnosis of metastatic or locally advanced unresectable disease will be accepted. New tumor samples can be obtained as part of patient’s routine clinical care. Specimens with limited tumor content and fine needle aspirates are inadequate for defining tumor HER2 mutation status.",
      "quote": "All patients must provide an existing FFPE tumor sample for retrospective central HER2 testing."
    },
    {
      "kind": "inclusion",
      "text": "Has measurable target disease assessed by the Investigator based on RECIST v1.1.",
      "quote": "Has measurable target disease assessed by the Investigator based on RECIST v1.1."
    },
    {
      "kind": "inclusion",
      "text": "WHO/ECOG performance status 0-1.",
      "quote": "WHO/ECOG performance status 0-1."
    },
    {
      "kind": "inclusion",
      "text": "LVEF ≥ 50% by either ECHO or MUGA scan within 28 days before treatment assignment.",
      "quote": "LVEF ≥ 50% by either ECHO or MUGA scan within 28 days before treatment assignment.",
      "thresholds": [
        {
          "test": "LVEF",
          "op": ">=",
          "value": 50,
          "unit": "%"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Adequate organ and bone marrow function within 14 days before IP administration, defined as: Platelet count ≥ 100000/mm3. (Platelet transfusion is not allowed within 1 week prior to screening assessment) Hemoglobin ≥ 18 g/dL. NOTE: Patients requiring ongoing transfusions or growth factor support to maintain hemoglobin ≥9 g/dL are not eligible. (> 8 g/dL in Gastric Cancer / Gastroesophageal Cancer Indications) (Red blood cell transfusion is not allowed within 1 week prior to screening assessment) Absolute neutrophil count ≥ 1500/mm3. (G-CSF administration is not allowed within 1 week prior to screening assessment) Creatinine clearance ≥ 30 mL/min (as calculated using the Cockcroft and Gault equation) ALT / AST ≤ 3 × ULN, < 5 × ULN in patients with liver metastases. Total bilirubin ≤ 1.5 × ULN if no liver metastases or < 3 x ULN in the presence of documented Gilbert’s Syndrome (unconjugated hyperbilirubinemia) or liver metastases at baseline. Serum albumin ≥ 2.5 g/dL INR/PT, and either PTT or aPTT ≤ 1.5 × ULN",
      "quote": "Adequate organ and bone marrow function within 14 days before IP administration",
      "thresholds": [
        {
          "test": "Platelet count",
          "op": ">=",
          "value": 100000,
          "unit": "/mm3"
        },
        {
          "test": "Hemoglobin",
          "op": ">=",
          "value": 18,
          "unit": "g/dL"
        },
        {
          "test": "Absolute neutrophil count",
          "op": ">=",
          "value": 1500,
          "unit": "/mm3"
        },
        {
          "test": "Creatinine clearance",
          "op": ">=",
          "value": 30,
          "unit": "mL/min"
        },
        {
          "test": "ALT",
          "op": "<=",
          "value": 3,
          "unit": "x ULN"
        },
        {
          "test": "AST",
          "op": "<=",
          "value": 3,
          "unit": "x ULN"
        },
        {
          "test": "Total bilirubin",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "Serum albumin",
          "op": ">=",
          "value": 2.5,
          "unit": "g/dL"
        },
        {
          "test": "INR/PT",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "PTT or aPTT",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Has adequate treatment washout period before study drug treatment, defined as: Major surgery: ≥ 4 weeks. Radiation therapy including palliative stereotactic radiation therapy to chest: ≥ 4 weeks (palliative stereotactic radiation therapy to other areas ≥ 2 weeks). Anti-cancer chemotherapy (Immunotherapy [non-antibody-based therapy]), retinoid therapy, mBC; hormonal therapy: ≥ 3 weeks (≥ 2 weeks or 5 half-lives, whichever is longer, for small-molecule targeted agents such as 5-fluorouracil-based agents, folinate agents or weekly paclitaxel; ≥ 6 weeks for nitrosureas or mitomycin C). Antibody-based anti-cancer therapy: ≥ 4 weeks. Chloroquine / Hydroxychloroquine: > 14 days.",
      "quote": "Has adequate treatment washout period before study drug treatment"
    },
    {
      "kind": "inclusion",
      "text": "Evidence of post-menopausal status or negative serum pregnancy test for females of childbearing potential who are sexually active with a non-sterilized male partner. For women of childbearing potential, a negative result for serum pregnancy test (test must have a sensitivity of at least 25 mIU/mL) must be available at the screening visit and urine beta-human chorionic gonadotropin pregnancy test prior to each administration of IP. Women will be considered post-menopausal if they have been amenorrheic for 12 months without an alternative medical cause. The following age-specific requirements apply: Women aged ≥ 50 years would be considered post-menopausal if they have been amenorrheic for 12 months or more following cessation of exogenous hormonal treatments and if they have luteinizing hormone and follicle-stimulating hormone levels in the post-menopausal range for the site. Women aged ≤ 50 years would be considered post-menopausal if they have been amenorrheic for 12 months or more following cessation of all exogenous hormonal treatments, had radiation-induced oophorectomy with last menses > 1 year ago, had chemotherapy-induced menopause with > 1 year-interval since last menses, or underwent surgical sterilization (bilateral oophorectomy or hysterectomy).",
      "quote": "Evidence of post-menopausal status or negative serum pregnancy test for females of childbearing potential"
    },
    {
      "kind": "inclusion",
      "text": "Female patients of childbearing potential who are sexually active with a non-sterilized male partner must use at least one highly effective method of contraception (Table 10) from the time of screening and must agree to continue using such precautions for at least 7 months after the last dose of IP. Not all methods of contraception are highly effective. Female patients must refrain from egg cell donation and breastfeeding while on study and for 7 months after the last dose of IP. Not engaging in sexual activity for the duration of the study and drug washout period is an acceptable practice; however, periodic or occasional abstinence, the rhythm method, and the withdrawal method are not acceptable methods of contraception.",
      "quote": "Female patients of childbearing potential who are sexually active with a non-sterilized male partner must use at least one highly effective method of contraception"
    },
    {
      "kind": "inclusion",
      "text": "Non-sterilized male patients who are sexually active with a female partner of childbearing potential must use a condom with spermicide from screening to at least 4 months after the final dose of IP. Not engaging in sexual activity for the duration of the study and drug washout period is an acceptable practice; however, periodic or occasional abstinence, the rhythm method, and the withdrawal method are not acceptable methods of contraception. It is strongly recommended for the female partners of a male patient to also use at least one highly effective method of throughout this period, as described in Table 10. In addition, male patients should refrain from fathering a child or freezing or donating sperm from screening, throughout the study treatment period, and for at least 4 months after the last dose of IP.",
      "quote": "Non-sterilized male patients who are sexually active with a female partner of childbearing potential must use a condom with spermicide"
    },
    {
      "kind": "inclusion",
      "text": "Female patients must not donate, or retrieve for their own use, ova from the time of screening and throughout the study treatment period, and for at least 7 months after the final study drug administration.",
      "quote": "Female patients must not donate, or retrieve for their own use, ova from the time of screening"
    }
  ]
}
